    var step = R.zoom ? (small() ? 10 : 5) : (small() ? 84 : 42); for (var k = a; k <= b; k += step) { var tx = el("text", { x: sx(k), y: H - 6, class: "ax", "text-anchor": "middle" }, s); tx.textContent = dLabel(X.d[k], !R.zoom && (k === a)); }
