      var c = el("circle", { cx: x, cy: sy(X.p[mm.i]), r: k === R.sel ? 7 : 5, class: "ldot " + (/Hike/.test(mm.dec) ? "hike" : "hold") + (k === R.sel ? " on" : ""), "data-k": k, tabindex: 0 }, s);
