      tip.hidden = false; tip.innerHTML = "<b>" + dLabel(X.d[i], true) + "</b> " + X.p[i].toFixed(4) + (CH[i] != null ? ' <span class="' + (CH[i] >= 0 ? "up" : "dn") + '">' + pct(CH[i]) + "</span>" : "");
